using Microsoft.Extensions.Logging.Abstractions;using StockSyncAI.Api.Configuration;using StockSyncAI.Api.Database;using StockSyncAI.Api.Models;
namespace StockSyncAI.Tests.Database;
public sealed class InvoicePostingRepositoryTests:IDisposable
{
 private readonly string dir=Path.Combine(Path.GetTempPath(),$"stocksync-posting-{Guid.NewGuid():N}");
 [Fact] public async Task Repository_GuardsTransitionsAndRecoversUnknownOutcome(){var(repo,invoice)=await Create();var f=new string('a',64);var p=await repo.PrepareAsync(invoice,f,"{}",DateTimeOffset.UtcNow);Assert.Equal(PostingStates.Prepared,p.State);Assert.True(await repo.TryStartAsync(p.Id,DateTimeOffset.UtcNow));Assert.False(await repo.TryStartAsync(p.Id,DateTimeOffset.UtcNow));Assert.Equal(1,await repo.RecoverInterruptedAsync(DateTimeOffset.UtcNow));var u=await repo.GetAsync(invoice,f);Assert.Equal(PostingStates.OutcomeUnknown,u!.State);var retry=await repo.PrepareAsync(invoice,f,"changed",DateTimeOffset.UtcNow);Assert.Equal(PostingStates.OutcomeUnknown,retry.State);Assert.Equal("{}",retry.SnapshotJson);}
 [Fact] public async Task PostedVersion_CannotBePreparedOrStartedAgain(){var(repo,invoice)=await Create();var f=new string('b',64);var p=await repo.PrepareAsync(invoice,f,"{}",DateTimeOffset.UtcNow);await repo.TryStartAsync(p.Id,DateTimeOffset.UtcNow);await repo.SetOutcomeAsync(p.Id,PostingStates.Posted,null,"{}",DateTimeOffset.UtcNow,DateTimeOffset.UtcNow);Assert.Equal(PostingStates.Posted,(await repo.PrepareAsync(invoice,f,"x",DateTimeOffset.UtcNow)).State);Assert.False(await repo.TryStartAsync(p.Id,DateTimeOffset.UtcNow));}
 private async Task<(InvoicePostingRepository,Guid)> Create(){var paths=new ApplicationPaths(dir);var factory=new SqliteConnectionFactory(paths);await new SqliteDatabaseInitializer(paths,factory,NullLogger<SqliteDatabaseInitializer>.Instance).InitializeAsync();var id=Guid.NewGuid();await new InvoiceRepository(factory).InsertAsync(new(id,"i.pdf",$"{id:N}.pdf",".pdf","application/pdf",1,new string('a',64),DateTimeOffset.UtcNow,InvoiceRecord.UploadedStatus,Guid.NewGuid().ToString("D")));return(new(factory),id);}
 public void Dispose(){Microsoft.Data.Sqlite.SqliteConnection.ClearAllPools();if(Directory.Exists(dir))Directory.Delete(dir,true);}
}
